CREATE TABLE IF NOT EXISTS ik_d1_erasure_journal (id TEXT PRIMARY KEY, destination TEXT NOT NULL, recorded_at TEXT NOT NULL, records_erased INTEGER NOT NULL CHECK(records_erased>=0), jobs_retired INTEGER NOT NULL CHECK(jobs_retired>=0), streams_retired INTEGER NOT NULL CHECK(streams_retired>=0), stores_json TEXT NOT NULL CHECK(json_valid(stores_json)));
CREATE INDEX IF NOT EXISTS ik_d1_erasure_journal_time ON ik_d1_erasure_journal(destination, recorded_at);
CREATE TRIGGER IF NOT EXISTS ik_d1_erasure_journal_insert BEFORE INSERT ON ik_d1_erasure_journal WHEN EXISTS(SELECT 1 FROM ik_d1_erasure_journal WHERE id=NEW.id) BEGIN SELECT RAISE(ABORT,'IMPORT_ERASURE_JOURNAL_APPEND_ONLY'); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_retirement_insert BEFORE INSERT ON ik_d1_retirements WHEN EXISTS(SELECT 1 FROM ik_d1_retirements WHERE id=NEW.id AND kind=NEW.kind) BEGIN SELECT RAISE(ABORT,'IMPORT_RETIREMENT_CHANGED'); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_erasure_journal_update BEFORE UPDATE ON ik_d1_erasure_journal BEGIN SELECT RAISE(ABORT,'IMPORT_ERASURE_JOURNAL_APPEND_ONLY'); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_erasure_journal_delete BEFORE DELETE ON ik_d1_erasure_journal BEGIN SELECT RAISE(ABORT,'IMPORT_ERASURE_JOURNAL_APPEND_ONLY'); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_retirement_update BEFORE UPDATE ON ik_d1_retirements BEGIN SELECT RAISE(ABORT,'IMPORT_RETIREMENT_CHANGED'); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_retirement_delete BEFORE DELETE ON ik_d1_retirements BEGIN SELECT RAISE(ABORT,'IMPORT_RETIREMENT_CHANGED'); END;
CREATE TABLE IF NOT EXISTS ik_d1_erasure_tally (receipt_id TEXT NOT NULL, store TEXT NOT NULL, image TEXT NOT NULL);
DROP TRIGGER IF EXISTS ik_d1_stream_revision_update;
CREATE TRIGGER ik_d1_stream_revision_update BEFORE UPDATE ON ik_d1_stream_revisions WHEN NEW.stream_id IS NOT OLD.stream_id OR NEW.destination IS NOT OLD.destination OR NEW.mapping_version IS NOT OLD.mapping_version OR NEW.principal_id IS NOT OLD.principal_id OR NEW.fingerprint IS NOT OLD.fingerprint OR NEW.total IS NOT OLD.total OR NEW.layout_hash IS NOT OLD.layout_hash OR NEW.layout_revision<OLD.layout_revision OR NEW.progress_revision<=OLD.progress_revision OR ((NEW.namespace IS NOT OLD.namespace OR NEW.operation_key IS NOT OLD.operation_key) AND NOT (NEW.namespace='' AND NEW.operation_key='' AND NOT EXISTS(SELECT 1 FROM ik_d1_streams WHERE id=OLD.stream_id) AND EXISTS(SELECT 1 FROM ik_d1_retirements WHERE id=OLD.stream_id AND kind='stream'))) BEGIN SELECT RAISE(ABORT,'IMPORT_STREAM_REVISION_CHANGED'); END;

-- Existing bookings retain their managed-calendar obligation. New schedule-only
-- bookings persist absence separately from the provider delivery state.
ALTER TABLE bookings ADD COLUMN calendar_required INTEGER NOT NULL DEFAULT 1 CHECK (calendar_required IN (0, 1));

-- Source admission is durable across isolates. Writer receipts never expire:
-- a crashed writer refuses export, while ordinary use can continue. A hosted
-- export lease expires so an abandoned client cannot hold the app in maintenance.
CREATE TABLE dial_portability_admission (
 id TEXT PRIMARY KEY,
 kind TEXT NOT NULL CHECK (kind IN ('writer','export')),
 expires_at INTEGER,
 CHECK ((kind='writer' AND expires_at IS NULL) OR (kind='export' AND expires_at IS NOT NULL))
);
CREATE UNIQUE INDEX dial_portability_one_export ON dial_portability_admission(kind) WHERE kind='export';

-- Base accounts/schema/provider-control.sql: local dependency setup completion.
-- Existing owners start complete; a future first-owner bootstrap starts pending.
CREATE TABLE IF NOT EXISTS oa_auth_settings (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1), idp_sign_in INTEGER NOT NULL CHECK(idp_sign_in IN (0,1)), generation INTEGER NOT NULL DEFAULT 0, first_setup INTEGER NOT NULL DEFAULT 0
);
INSERT INTO oa_auth_settings(singleton,idp_sign_in,generation,first_setup)
 SELECT 1,0,0,0 WHERE EXISTS(SELECT 1 FROM oa_bootstrap) ON CONFLICT DO NOTHING;
CREATE TRIGGER IF NOT EXISTS oa_first_setup_provider_setting AFTER INSERT ON oa_bootstrap BEGIN
 INSERT INTO oa_auth_settings(singleton,idp_sign_in,generation,first_setup) VALUES(1,0,0,1) ON CONFLICT DO NOTHING;
END;

-- import-kit d1PreparationStepsSchema: control rows for preparations made across
-- requests (prepareD1ImportSteps). Erasure, cancellation and header retirement read it.
CREATE TABLE IF NOT EXISTS ik_d1_preparation_steps (id TEXT PRIMARY KEY, destination TEXT NOT NULL, namespace TEXT NOT NULL, mapping_version TEXT NOT NULL, principal_id TEXT NOT NULL, operation_key TEXT NOT NULL, reversal_policy TEXT NOT NULL, codec_id TEXT, source_digest TEXT NOT NULL, total INTEGER NOT NULL, records INTEGER NOT NULL DEFAULT 0, stages TEXT NOT NULL DEFAULT '[]', phase TEXT NOT NULL CHECK(phase IN ('collecting','hashing','combining','prepared')), hash_json TEXT, fingerprint TEXT, verified_revision INTEGER, revision INTEGER NOT NULL DEFAULT 0, UNIQUE(destination,principal_id,operation_key));

CREATE TRIGGER IF NOT EXISTS ik_d1_preparation_steps_binding BEFORE UPDATE OF id,destination,namespace,mapping_version,principal_id,operation_key,reversal_policy,codec_id,source_digest,total ON ik_d1_preparation_steps BEGIN SELECT RAISE(ABORT,'IMPORT_PREPARATION_BINDING_CHANGED'); END;

CREATE TRIGGER IF NOT EXISTS ik_d1_preparation_steps_revision BEFORE UPDATE ON ik_d1_preparation_steps WHEN NEW.revision<>OLD.revision+1 BEGIN SELECT RAISE(ABORT,'IMPORT_PREPARATION_CHANGED'); END;

-- Additive provider controls. An absent setting means off, including upgrades.
CREATE TABLE IF NOT EXISTS oa_auth_settings (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1), idp_sign_in INTEGER NOT NULL CHECK(idp_sign_in IN (0,1)), generation INTEGER NOT NULL DEFAULT 0, first_setup INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS oa_auth_audit (
 id TEXT PRIMARY KEY, actor_id TEXT NOT NULL, action TEXT NOT NULL, value TEXT NOT NULL, created_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS oa_provider_sessions (
 session_id TEXT PRIMARY KEY, issuer TEXT NOT NULL, subject TEXT NOT NULL, sid TEXT, generation INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS oa_provider_session_identity ON oa_provider_sessions(issuer,subject,sid);
CREATE TABLE IF NOT EXISTS oa_logout_events (
 issuer TEXT NOT NULL, jti TEXT NOT NULL, consumed_at INTEGER NOT NULL CHECK(consumed_at>=0), PRIMARY KEY(issuer,jti)
);

CREATE TRIGGER IF NOT EXISTS oa_first_setup_provider_setting AFTER INSERT ON oa_bootstrap BEGIN
 INSERT INTO oa_auth_settings(singleton,idp_sign_in,generation,first_setup) VALUES(1,0,0,1) ON CONFLICT DO NOTHING;
END;

CREATE TABLE IF NOT EXISTS oa_credentials (
 id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE, operator_id TEXT NOT NULL REFERENCES oa_operators(id),
 operator_version INTEGER, kind TEXT NOT NULL, expires_at INTEGER NOT NULL, revoked_at INTEGER
);

-- Session provenance for OIDC pins. Apply as a new migration on existing stores.
-- External admission has no OIDC pin and does not require OIDC protocol tables.
CREATE TABLE IF NOT EXISTS oa_provider_session_pins (
 session_id TEXT PRIMARY KEY, provider_id TEXT NOT NULL, issuer TEXT NOT NULL,
 client_id TEXT NOT NULL, linked_at INTEGER NOT NULL
);

-- Ephemeral app-local setup attempts are never exported. A native claim binds
-- only attempts opened before that claim to its exact owner/session authority,
-- in its own bootstrap transaction.
CREATE TABLE IF NOT EXISTS oa_setup_links (
 interface TEXT PRIMARY KEY, attempt_id TEXT NOT NULL, expires_at INTEGER NOT NULL,
 owner_id TEXT, owner_version INTEGER, session_id TEXT,
 completed INTEGER NOT NULL DEFAULT 0 CHECK(completed IN (0,1))
);
CREATE TRIGGER IF NOT EXISTS oa_native_claim_closes_provider_setup AFTER INSERT ON oa_sessions
WHEN NEW.kind='native' AND NOT EXISTS(SELECT 1 FROM oa_sessions WHERE operator_id=NEW.operator_id AND id!=NEW.id) AND EXISTS(SELECT 1 FROM oa_bootstrap WHERE claim_id=NEW.operator_id AND claimed_at=NEW.created_at)
BEGIN
 UPDATE oa_auth_settings SET first_setup=0 WHERE singleton=1 AND NOT EXISTS(
  SELECT 1 FROM oa_setup_links WHERE interface='oidc-provider@1' AND completed=0 AND owner_id IS NULL AND expires_at>NEW.created_at
 );
 UPDATE oa_setup_links SET owner_id=NEW.operator_id,owner_version=NEW.operator_version,session_id=NEW.id
 WHERE owner_id IS NULL AND completed=0 AND expires_at>NEW.created_at;
END;

-- Add the Managed relay identity without changing any existing provider health.
ALTER TABLE provider_connection_health RENAME TO provider_connection_health_before_managed_mail;
CREATE TABLE provider_connection_health (
  provider TEXT PRIMARY KEY NOT NULL CHECK (provider IN ('google_calendar', 'resend', 'sendgrid', 'rer', 'development')),
  status TEXT NOT NULL CHECK (status IN ('healthy', 'unhealthy')),
  last_checked_at TEXT,
  unhealthy_code TEXT,
  alert_state TEXT NOT NULL CHECK (alert_state IN ('healthy_announced', 'unhealthy_announced', 'unannounced')),
  alert_cycle INTEGER NOT NULL DEFAULT 0 CHECK (alert_cycle >= 0),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
INSERT INTO provider_connection_health SELECT * FROM provider_connection_health_before_managed_mail;
DROP TABLE provider_connection_health_before_managed_mail;

-- Expand question kinds while preserving existing public identities and ordering.
-- No triggers or foreign keys reference event_questions in the preceding schema.
CREATE TABLE event_questions_v3 (
  id TEXT PRIMARY KEY NOT NULL,
  event_type_id TEXT NOT NULL REFERENCES event_types(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('text', 'textarea', 'phone', 'single_choice', 'dropdown', 'multiple_choice', 'checkbox')),
  label TEXT NOT NULL,
  required INTEGER NOT NULL DEFAULT 0 CHECK (required IN (0, 1)),
  options_json TEXT NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  public_key TEXT
);

INSERT INTO event_questions_v3 (id, event_type_id, position, kind, label, required, options_json, created_at, updated_at, public_key)
SELECT id, event_type_id, position, kind, label, required, options_json, created_at, updated_at, public_key
FROM event_questions;

DROP TABLE event_questions;
ALTER TABLE event_questions_v3 RENAME TO event_questions;
CREATE UNIQUE INDEX event_questions_position_idx ON event_questions(event_type_id, position);
CREATE UNIQUE INDEX event_questions_public_key_idx ON event_questions(event_type_id, public_key);

-- Preserve every event and its configured increment while widening the constraint.
ALTER TABLE event_types ADD COLUMN scheduling_increment INTEGER NOT NULL DEFAULT 15
  CHECK (scheduling_increment IN (5, 10, 15, 30, 45, 60));
UPDATE event_types SET scheduling_increment = slot_increment_minutes;
ALTER TABLE event_types DROP COLUMN slot_increment_minutes;
ALTER TABLE event_types RENAME COLUMN scheduling_increment TO slot_increment_minutes;
ALTER TABLE event_types ADD COLUMN booking_horizon_mode TEXT NOT NULL DEFAULT 'calendar_days'
  CHECK (booking_horizon_mode IN ('calendar_days', 'weekdays', 'fixed_range', 'indefinite'));
ALTER TABLE event_types ADD COLUMN booking_start_date TEXT;
ALTER TABLE event_types ADD COLUMN booking_end_date TEXT;

ALTER TABLE event_types ADD COLUMN duration_options_json TEXT NOT NULL DEFAULT '[]'
  CHECK (json_valid(duration_options_json) AND json_type(duration_options_json) = 'array');
UPDATE event_types SET duration_options_json = json_array(duration_minutes);
-- Existing import plans may omit the additive column; keep their saved duration.
CREATE TRIGGER event_duration_options_insert AFTER INSERT ON event_types
WHEN NEW.duration_options_json = '[]'
BEGIN UPDATE event_types SET duration_options_json = json_array(NEW.duration_minutes) WHERE id = NEW.id; END;

ALTER TABLE event_types ADD COLUMN post_booking_redirect_json TEXT DEFAULT NULL
  CHECK (post_booking_redirect_json IS NULL OR (json_valid(post_booking_redirect_json) AND json_type(post_booking_redirect_json) = 'object'));
ALTER TABLE event_questions ADD COLUMN private INTEGER NOT NULL DEFAULT 0 CHECK (private IN (0, 1));
ALTER TABLE bookings ADD COLUMN attribution_json TEXT NOT NULL DEFAULT '{}'
  CHECK (json_valid(attribution_json) AND json_type(attribution_json) = 'object');
ALTER TABLE bookings ADD COLUMN post_booking_redirect_url TEXT DEFAULT NULL;
